def fingerprint_report(items):return [{"seed":x.seed,"radius":x.radius,"topology_hash":x.topology_hash,"semantic_hash":x.semantic_hash,"nodes":list(x.nodes),"confidence":x.confidence,"features":{"component_kinds":list(x.features.component_kinds),"component_degrees":list(x.features.component_degrees),"net_degrees":list(x.features.net_degrees),"net_roles":list(x.features.net_roles),"pin_edge_count":x.features.pin_edge_count}} for x in items]
